/**
 * Tooltip-based metadata badges for ObservationDetailView
 * These badges use BreakdownTooltip to show detailed cost/usage information
 */

import { Badge, BadgeShell } from "@/src/components/design-system/Badge/Badge";
import {
  BreakdownTooltip,
  type CostSource,
  type PriceSource,
} from "@/src/features/traces/components/BreakdownTooltip";
import { usdFormatter, numberFormatter } from "@/src/utils/numbers";
import { InfoIcon } from "lucide-react";

export function CostBadge({
  totalCost,
  costDetails,
  priceSource,
  costSource,
}: {
  totalCost: number;
  costDetails: Record<string, number>;
  priceSource?: PriceSource;
  costSource?: CostSource;
}) {
  if (!hasBreakdown(costDetails)) {
    return <Badge text={usdFormatter(totalCost)} />;
  }
  return (
    <BreakdownTooltip
      details={costDetails}
      isCost={true}
      priceSource={priceSource}
      costSource={costSource}
    >
      <Badge
        label="cost"
        text={usdFormatter(totalCost)}
        trailingIcon={InfoIcon}
      />
    </BreakdownTooltip>
  );
}

/** A breakdown of nothing but zeros has nothing to say. */
export const hasBreakdown = (details: Record<string, number>) =>
  Object.values(details).some((value) => value > 0);

export function UsageBadge({
  totalUsage,
  usageDetails,
}: {
  totalUsage: number;
  usageDetails: Record<string, number>;
}) {
  const tokenText = totalUsage > 0 ? numberFormatter(totalUsage, 0) : undefined;

  if (tokenText && !hasBreakdown(usageDetails)) {
    return <Badge text={tokenText} />;
  }

  return (
    <BreakdownTooltip details={usageDetails} isCost={false}>
      {tokenText ? (
        <Badge label="tokens" text={tokenText} trailingIcon={InfoIcon} />
      ) : (
        <BadgeShell aria-label="View usage breakdown">
          <InfoIcon aria-hidden className="size-3" />
        </BadgeShell>
      )}
    </BreakdownTooltip>
  );
}

import { readFileSync, writeFileSync } from "fs";

/**
 * Merges detailed observation data (input/output/metadata) into the base trace file.
 * how to use? SEE README.md
 *
 * Usage: tsx merge-observations.ts <base-file> <detailed-obs-file> <output-file>
 *
 * Example:
 *   tsx merge-observations.ts pydantic-base.json pydantic-details.json pydantic-ai.json
 *
 */

const [baseFile, detailedFile, outputFile] = process.argv.slice(2);

if (!baseFile || !detailedFile || !outputFile) {
  console.error(
    "Usage: tsx merge-observations.ts <base-file> <detailed-obs-file> <output-file>",
  );
  process.exit(1);
}

const baseData = JSON.parse(readFileSync(baseFile, "utf-8"));
const detailedObs = JSON.parse(readFileSync(detailedFile, "utf-8"));

// Build ID to detailed observation map
const obsMap = new Map<string, any>();
for (const obs of Object.values(detailedObs)) {
  obsMap.set((obs as any).id, obs);
}

// Merge input/output/metadata into observations array
const mergedObservations = baseData.observations.map((obs: any) => {
  const detailed = obsMap.get(obs.id);
  if (detailed) {
    return {
      ...obs,
      input: detailed.input,
      output: detailed.output,
      metadata: detailed.metadata,
    };
  }
  return obs;
});

// demo project
const PROJECT_ID = "7a88fb47-b4e2-43b8-a06c-a5ce950dc53a";

// Remove observations from trace, create final structure
const output = {
  trace: {
    ...baseData.trace,
    projectId: PROJECT_ID,
  },
  observations: mergedObservations.map((obs: any) => ({
    ...obs,
    projectId: PROJECT_ID,
  })),
};

// Remove observations array from trace if it exists
delete (output.trace as any).observations;

writeFileSync(outputFile, JSON.stringify(output, null, 2));

console.log(`Merged ${mergedObservations.length} observations`);
console.log(`Wrote to ${outputFile}`);

import { describe, expect, it } from "vitest";
import {
  ensureExperimentRootFilter,
  isExperimentEvaluationRule,
  normalizeEvaluationRuleTarget,
} from "./experimentRuleNormalization";
import { EvalTargetObject } from "./types";

const datasetFilter = {
  type: "stringOptions" as const,
  column: "experimentDatasetId",
  operator: "any of" as const,
  value: ["dataset-id"],
};

describe("experiment rule normalization", () => {
  it("normalizes the legacy Dataset column used by migrated evaluators", () => {
    expect(
      normalizeEvaluationRuleTarget({
        targetObject: EvalTargetObject.EXPERIMENT,
        filter: [{ ...datasetFilter, column: "Dataset" }],
      }),
    ).toEqual({
      targetObject: EvalTargetObject.EVENT,
      filter: [
        datasetFilter,
        {
          type: "boolean",
          column: "isExperimentItemRootSpan",
          operator: "=",
          value: true,
        },
      ],
    });
  });

  it("normalizes the legacy datasetId column used before event rules", () => {
    expect(
      normalizeEvaluationRuleTarget({
        targetObject: EvalTargetObject.EXPERIMENT,
        filter: [{ ...datasetFilter, column: "datasetId" }],
      }),
    ).toEqual({
      targetObject: EvalTargetObject.EVENT,
      filter: [
        datasetFilter,
        {
          type: "boolean",
          column: "isExperimentItemRootSpan",
          operator: "=",
          value: true,
        },
      ],
    });
  });

  it("normalizes the legacy experiment target to the canonical event representation", () => {
    expect(
      normalizeEvaluationRuleTarget({
        targetObject: EvalTargetObject.EXPERIMENT,
        filter: [datasetFilter],
      }),
    ).toEqual({
      targetObject: EvalTargetObject.EVENT,
      filter: [
        datasetFilter,
        {
          type: "boolean",
          column: "isExperimentItemRootSpan",
          operator: "=",
          value: true,
        },
      ],
    });
  });

  it("recognizes either experiment representation", () => {
    expect(
      isExperimentEvaluationRule({
        targetObject: EvalTargetObject.EXPERIMENT,
        filter: [],
      }),
    ).toBe(true);
    expect(
      isExperimentEvaluationRule({
        targetObject: EvalTargetObject.EVENT,
        filter: ensureExperimentRootFilter([]),
      }),
    ).toBe(true);
  });

  it("replaces duplicate or conflicting root filters idempotently", () => {
    const filter = [
      datasetFilter,
      {
        type: "boolean" as const,
        column: "isExperimentItemRootSpan",
        operator: "<>" as const,
        value: false,
      },
      {
        type: "boolean" as const,
        column: "isExperimentItemRootSpan",
        operator: "=" as const,
        value: true,
      },
    ];

    const normalized = ensureExperimentRootFilter(filter);
    expect(normalized).toEqual([
      datasetFilter,
      {
        type: "boolean",
        column: "isExperimentItemRootSpan",
        operator: "=",
        value: true,
      },
    ]);
    expect(ensureExperimentRootFilter(normalized)).toEqual(normalized);
  });
});
